labs.fixedCode:
#include <stdio.h>
#include <string.h>

int main(void) {
    char buf[8];
    printf("Enter input: ");
    fgets(buf, sizeof(buf), stdin);  // SAFE: length-bounded
    // strip trailing newline
    size_t len = strlen(buf);
    if (len > 0 && buf[len-1] == '\n') buf[len-1] = '\0';
    printf("You said: %s\n", buf);
    return 0;
}

