#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char* secret = malloc(32);
    strcpy(secret, "password=hunter2");

    free(secret);        // memory returned to allocator

    char* reuse = malloc(32);       // same block reused!
    strcpy(reuse, "ATTACKER_DATA");

    printf("%s\n", secret);  // BUG: secret is freed!
    free(reuse);
}

labs.fixedCode:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char* secret = malloc(32);
    strcpy(secret, "password=hunter2");

    free(secret);
    secret = NULL;       // FIX: nullify immediately

    if (secret != NULL) {
        printf("%s\n", secret);
    } else {
        printf("[guard] pointer is NULL — use prevented\n");
    }
}

